CREATE TABLE projection_upgrade_state AS SELECT dirty,version FROM projection_state WHERE id=1;
-- Evidência e vigência não são inferidas de um catálogo manual.
ALTER TABLE cargos_autoridades ADD COLUMN fonte_url TEXT;
ALTER TABLE cargos_autoridades ADD COLUMN conferido_em TEXT;
ALTER TABLE cargos_autoridades ADD COLUMN evidencia_verificada INTEGER NOT NULL DEFAULT 0;
CREATE TABLE qualidade_dados_eventos (
    id INTEGER PRIMARY KEY,
    entidade TEXT NOT NULL,
    registro_id INTEGER NOT NULL,
    campo TEXT NOT NULL,
    valor_anterior TEXT,
    motivo TEXT NOT NULL,
    criado_em TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP
);

-- O identificador da fonte permanece estável quando um valor é retificado.
ALTER TABLE despesas_parlamentares ADD COLUMN id_origem TEXT;
CREATE UNIQUE INDEX idx_ceap_id_origem ON despesas_parlamentares(casa_legislativa,id_origem) WHERE id_origem IS NOT NULL;
CREATE TABLE despesas_parlamentares_versoes (
    id INTEGER PRIMARY KEY,
    despesa_id INTEGER NOT NULL,
    id_origem TEXT,
    anterior_json TEXT NOT NULL,
    atual_json TEXT NOT NULL,
    alterado_em TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP
);
CREATE INDEX idx_ceap_versoes_despesa ON despesas_parlamentares_versoes(despesa_id,id);
CREATE TRIGGER ceap_historico_retificacao AFTER UPDATE ON despesas_parlamentares
WHEN OLD.valor_liquido IS NOT NEW.valor_liquido OR OLD.data_emissao IS NOT NEW.data_emissao
  OR OLD.fornecedor_cnpj_cpf IS NOT NEW.fornecedor_cnpj_cpf OR OLD.numero_documento IS NOT NEW.numero_documento
  OR OLD.categoria_despesa IS NOT NEW.categoria_despesa OR OLD.detalhes_litros IS NOT NEW.detalhes_litros
BEGIN
    INSERT INTO despesas_parlamentares_versoes(despesa_id,id_origem,anterior_json,atual_json)
    VALUES(NEW.id,NEW.id_origem,
        json_object('valor_liquido',OLD.valor_liquido,'data_emissao',OLD.data_emissao,'fornecedor',OLD.fornecedor_cnpj_cpf,'numero_documento',OLD.numero_documento,'categoria',OLD.categoria_despesa,'litros',OLD.detalhes_litros),
        json_object('valor_liquido',NEW.valor_liquido,'data_emissao',NEW.data_emissao,'fornecedor',NEW.fornecedor_cnpj_cpf,'numero_documento',NEW.numero_documento,'categoria',NEW.categoria_despesa,'litros',NEW.detalhes_litros));
END;

CREATE TABLE auditoria_estado (
    id INTEGER PRIMARY KEY CHECK(id=1),
    revisao INTEGER NOT NULL DEFAULT 0,
    pendente INTEGER NOT NULL DEFAULT 1,
    concluida_em TEXT,
    metodologia TEXT NOT NULL DEFAULT 'alertas-locais-v1'
);
INSERT INTO auditoria_estado(id) VALUES(1);
CREATE INDEX idx_alertas_politico_id ON alertas_auditoria(json_extract(detalhes_json,'$.politico_id')) WHERE json_valid(detalhes_json);
CREATE INDEX idx_alertas_alvo_nome ON alertas_auditoria(alvo_nome);

